// Process CA AG RSS items
const items = $input.all();

return items.map(item => {
  const json = item.json;
  const text = ((json.title || '') + ' ' + (json.contentSnippet || json.description || '')).toLowerCase();

  // Check if fraud-related
  const fraudKeywords = /fraud|scheme|corruption|bribery|theft|scam|deceptive|settlement|lawsuit|charged|indicted|sentenced/i;
  if (!fraudKeywords.test(text)) return null;

  // Detect fraud type
  let fraudType = 'other';
  if (text.includes('healthcare') || text.includes('insurance')) fraudType = 'healthcare';
  else if (text.includes('consumer') || text.includes('scam')) fraudType = 'financial';
  else if (text.includes('tax')) fraudType = 'tax';
  else if (text.includes('environment')) fraudType = 'government';

  return {
    json: {
      title: json.title,
      source_url: json.link,
      source_name: 'CA Attorney General',
      published_at: json.pubDate || json.isoDate || new Date().toISOString(),
      summary: json.contentSnippet || json.description || null,
      fraud_type: fraudType,
      state: 'CA',
      importance_score: 70 // CA stories get priority
    }
  };
}).filter(Boolean);

// Parse MN AG HTML for press releases
// Note: This is a basic extraction - adjust selectors based on actual page structure
const html = $input.first().json.links || [];

const results = [];

// MN AG doesn't have RSS, so we need to parse the HTML
// This is a placeholder - you'll need to adjust based on actual page structure
for (const link of html.slice(0, 10)) {
  // Extract href and text from anchor tags
  const hrefMatch = link.match(/href=["']([^"']+)["']/);
  const textMatch = link.match(/>([^<]+)</);

  if (hrefMatch && textMatch) {
    const href = hrefMatch[1];
    const title = textMatch[1].trim();

    // Check if fraud-related
    const fraudKeywords = /fraud|scheme|corruption|bribery|theft|scam|settlement|lawsuit|charged/i;
    if (!fraudKeywords.test(title)) continue;

    results.push({
      json: {
        title: title,
        source_url: href.startsWith('http') ? href : 'https://www.ag.state.mn.us' + href,
        source_name: 'MN Attorney General',
        published_at: new Date().toISOString(),
        summary: null,
        fraud_type: 'other',
        state: 'MN',
        importance_score: 75 // MN stories get high priority
      }
    });
  }
}

return results;
